'use client';
import { useEffect, useRef, useState } from 'react';

let threePromise: Promise<void> | null = null;
let loaderPromise: Promise<void> | null = null;

function loadThree(): Promise<void> {
  if ((window as any).THREE) return Promise.resolve();
  if (!threePromise) {
    threePromise = new Promise<void>((resolve, reject) => {
      const s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js';
      s.onload = () => resolve();
      s.onerror = () => reject(new Error('Three.js load failed'));
      document.head.appendChild(s);
    });
  }
  return threePromise;
}

function loadGLTFLoader(): Promise<void> {
  if ((window as any).THREE?.GLTFLoader) return Promise.resolve();
  if (!loaderPromise) {
    loaderPromise = new Promise<void>((resolve, reject) => {
      const s = document.createElement('script');
      s.src = 'https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/loaders/GLTFLoader.js';
      s.onload = () => resolve();
      s.onerror = () => reject(new Error('GLTFLoader load failed'));
      document.head.appendChild(s);
    });
  }
  return loaderPromise;
}

export function GlbViewer({ src, height = 400 }: { src: string; height?: number }) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState(false);
  const frameRef = useRef<number>(0);
  const mountedRef = useRef(true);
  const rendererRef = useRef<any>(null);
  const cameraRef = useRef<any>(null);

  useEffect(() => {
    mountedRef.current = true;
    let scene: any, model: any;

    const init = async () => {
      try {
        await loadThree();
        if (!mountedRef.current) return;

        const THREE = (window as any).THREE;
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        // Poll until container has real dimensions (handles collapsed card case)
        let attempts = 0;
        while (attempts < 40) {
          if (container.clientWidth > 0 && container.clientHeight > 0) break;
          await new Promise(r => setTimeout(r, 100));
          attempts++;
        }
        if (!mountedRef.current) return;

        const w = container.clientWidth || 400;
        const h = container.clientHeight || height;

        const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        renderer.setSize(w, h, false);
        renderer.setClearColor(0x111111, 1);
        renderer.shadowMap.enabled = true;
        renderer.outputEncoding = THREE.sRGBEncoding;
        rendererRef.current = renderer;

        scene = new THREE.Scene();

        // Strong all-round lighting so model is always visible
        scene.add(new THREE.AmbientLight(0xffffff, 1.2));
        const key = new THREE.DirectionalLight(0xffffff, 2.0);
        key.position.set(5, 10, 7);
        key.castShadow = true;
        scene.add(key);
        const fill = new THREE.DirectionalLight(0xffffff, 0.8);
        fill.position.set(-5, 5, -5);
        scene.add(fill);
        const back = new THREE.DirectionalLight(0xffffff, 0.5);
        back.position.set(0, -5, -8);
        scene.add(back);

        const camera = new THREE.PerspectiveCamera(45, w / h, 0.001, 10000);
        cameraRef.current = camera;

        // Handle resize
        const ro = new ResizeObserver(() => {
          if (!container || !rendererRef.current || !cameraRef.current) return;
          const nw = container.clientWidth;
          const nh = container.clientHeight;
          if (nw === 0 || nh === 0) return;
          rendererRef.current.setSize(nw, nh, false);
          cameraRef.current.aspect = nw / nh;
          cameraRef.current.updateProjectionMatrix();
        });
        ro.observe(container);

        await loadGLTFLoader();
        if (!mountedRef.current) return;

        const loader = new (window as any).THREE.GLTFLoader();
        loader.load(src, (gltf: any) => {
          if (!mountedRef.current) return;
          model = gltf.scene;

          // Center model at origin
          const box = new THREE.Box3().setFromObject(model);
          const center = box.getCenter(new THREE.Vector3());
          const size = box.getSize(new THREE.Vector3());
          model.position.sub(center);

          scene.add(model);

          // Force resize in case container grew since init (e.g. card expanded)
          if (container && rendererRef.current && cameraRef.current) {
            const nw = container.clientWidth;
            const nh = container.clientHeight;
            if (nw > 0 && nh > 0) {
              rendererRef.current.setSize(nw, nh, false);
              cameraRef.current.aspect = nw / nh;
              cameraRef.current.updateProjectionMatrix();
            }
          }

          setLoaded(true);
          const sphere = box.getBoundingSphere(new THREE.Sphere());
          const radius = sphere.radius;
          const fovRad = (45 * Math.PI) / 180;
          const dist = (radius / Math.sin(fovRad / 2)) * 1.3;
          const cam = cameraRef.current;
          cam.position.set(dist * 0.6, dist * 0.4, dist * 0.8);
          cam.lookAt(0, 0, 0);
          cam.near = dist * 0.001;
          cam.far = dist * 10;
          cam.updateProjectionMatrix();

          setLoaded(true);

          const animate = () => {
            if (!mountedRef.current) return;
            frameRef.current = requestAnimationFrame(animate);
            model.rotation.y += 0.004;
            rendererRef.current.render(scene, cam);
          };
          animate();
        }, (progress: any) => {
          if (progress.total > 0) {
            console.log(`GLB loading: ${Math.round(progress.loaded / progress.total * 100)}% (${Math.round(progress.total / 1024 / 1024)}MB)`);
          }
        }, (err: any) => {
          console.error('GLB load failed:', src, err);
          if (mountedRef.current) setError(true);
        });

        return () => ro.disconnect();
      } catch (e) {
        console.error('GlbViewer init error:', e);
        if (mountedRef.current) setError(true);
      }
    };

    init();
    return () => {
      mountedRef.current = false;
      cancelAnimationFrame(frameRef.current);
      rendererRef.current?.dispose?.();
    };
  }, [src, height]);

  return (
    <div
      ref={containerRef}
      className="scanlines"
      style={{ width: '100%', height, background: 'var(--black)', position: 'relative', border: '1px solid var(--black)', overflow: 'hidden' }}
    >
      <div style={{ position: 'absolute', top: '0.75rem', left: '0.75rem', zIndex: 3, display: 'flex', flexDirection: 'column', gap: '0.2rem', pointerEvents: 'none' }}>
        <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.5rem', letterSpacing: '0.15em', color: 'var(--beige-dark)', opacity: 0.7 }}>○ 3D_MODEL</span>
        <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.45rem', letterSpacing: '0.1em', color: 'var(--gray-500)' }}>INTERACTIVE_ROTATION.glb</span>
      </div>
      <div style={{ position: 'absolute', top: '0.75rem', right: '0.75rem', zIndex: 3, pointerEvents: 'none' }}>
        <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.45rem', color: 'var(--gray-700)', letterSpacing: '0.1em' }}>three.js r128</span>
      </div>

      {!loaded && !error && (
        <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '1rem', zIndex: 2 }}>
          <SquareSpinner />
          <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.55rem', letterSpacing: '0.2em', color: 'var(--gray-500)', textTransform: 'uppercase' }}>loading model...</span>
        </div>
      )}
      {error && (
        <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '0.75rem', zIndex: 2 }}>
          <WireframeIcon />
          <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.55rem', letterSpacing: '0.15em', color: 'var(--gray-600)', textTransform: 'uppercase' }}>3D model unavailable</span>
        </div>
      )}

      {/* Canvas fills container via CSS — renderer size set explicitly in JS */}
      <canvas
        ref={canvasRef}
        style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', display: error ? 'none' : 'block' }}
      />
    </div>
  );
}

function SquareSpinner() {
  return (
    <div style={{ width: 36, height: 36, border: '1px solid var(--gray-700)', position: 'relative' }}>
      <div style={{ position: 'absolute', inset: 0, border: '1px solid var(--beige-dark)', animation: 'spin 1.4s linear infinite', transformOrigin: 'center' }} />
      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}

function WireframeIcon() {
  return (
    <svg width="64" height="64" viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity: 0.25 }}>
      <rect x="8" y="20" width="24" height="24" stroke="white" strokeWidth="0.75"/>
      <rect x="32" y="8" width="24" height="24" stroke="white" strokeWidth="0.75"/>
      <rect x="32" y="36" width="24" height="24" stroke="white" strokeWidth="0.75"/>
      <line x1="8" y1="20" x2="32" y2="8" stroke="white" strokeWidth="0.5"/>
      <line x1="32" y1="20" x2="56" y2="8" stroke="white" strokeWidth="0.5"/>
      <line x1="32" y1="32" x2="56" y2="32" stroke="white" strokeWidth="0.5"/>
      <line x1="8" y1="44" x2="32" y2="44" stroke="white" strokeWidth="0.5"/>
      <line x1="32" y1="44" x2="32" y2="60" stroke="white" strokeWidth="0.5"/>
    </svg>
  );
}
